%[text] ## Demo1: System Identification using chirp signal
%%
%[text] ### STEP 1: CHIRP EXCITATION
%[text] load settings for the experiment
clear; close all;
projectRoot = fileparts(fileparts(mfilename("fullpath")));
run(fullfile(projectRoot, "config", "config.m"));
load(fullfile(projectRoot, "config", "data", "pana_params.mat"));
feedbackFlag = 1;
Kd = tf(0.06,1); % open-loop system identification % open-loop system identification
%%
%[text] design excitation signal
Tend = 100; % simulation length
N = round(Tend/Ts);
t = Ts*(0:N-1);
Tcycle = 10; % cycle time of chirp signal
p = 0; % initial phase of chirp
f0 = 1; % min freq of chirp
f1 = min(2000, 0.4*sampleRateHz); % 1.6 kHz at 4 kHz, 2 kHz at 8 kHz
A = 1.2; % signal gain (preference: 0 < A < 1 for Pana motor, 0 < A < 2 for Beckhoff motor)
t_relative = t - floor(t/Tcycle)*Tcycle; % relative time inside chirp
k = (f1 - f0)/Tcycle; 
u = A*sin(p+(2*pi*(f0*t_relative + k/2 * t_relative.^2)));
%%
%[text] build simulink model "twomass\_exp\_2019a.slx" after executing this section
%[text] (build only needed 1 time.  rebuild required if you change the following parameters or the feedback controller Kd.)
set_ff = u(:);
set_ref = zeros(N,1);

open(fullfile(projectRoot, ModelName));
%%
%[text] execute experiment via simulink
%[text] \*make sure to close all simulink files before executing this section
open(fullfile(projectRoot, ModelName));
obtainMeasurement; %[output:0389ae77]
%%
count = measurement(1,:); % data counts
input = measurement(4,:); % control input [A]
output = measurement(5,:); % loadside position [um]
velocity = measurement(6,:);
torque = measurement(7,:);
lostPackages = setdiff(0:N-1, count);
lostPackagesNum = length(lostPackages); % Number of Lost Packages
assert(lostPackagesNum == 0 && all(diff(count) == 1), ...
    "Measurement contains missing or out-of-order samples.");
%[text] save experiment data
figure; %[output:14795463]
plot(count*Ts, input, count*Ts, torque); %[output:14795463]
title('position output'); %[output:14795463]
xlabel('time/s'); %[output:14795463]
%%
chirpResult = struct("input", input, "output", output, "velocity", velocity, ...
    "torque", torque, "Ts", Ts, "Tend", Tend, "Tcycle", Tcycle, ...
    "measurement_metadata", measurement_metadata, ...
    "measurement_source_path", measurement_source_path);
save_experiment_result(runDir, "chirp_result", chirpResult);
%%
%[text] ### STEP 2: TIME TREATMENT
%[text] download data
% load('data/chirp_result.mat');
% load("config/data/config.mat","bop");
%[text] remove transient periods
trans = 3; % number of transient periods
Nstart = round(trans*Tcycle/Ts)+1;
N = round(Tend/Ts); % total sample points of data
input = input(Nstart:N); % control input of plant
pos = output(Nstart:N);
vel = velocity(Nstart:N);
tor = torque(Nstart:N);
%%
%[text] ### STEP 3: NON-PARAMETRIC ESTIMATION
%[text] fft data and vizualize in freq domain position data
Fs = 1/Ts;
frfMaxHz = min(2000, 0.4*Fs);
frfFrequencyHz = logspace(log10(1), log10(frfMaxHz), 500);
segmentLength = min(round(2*Fs), length(input));
frfWindow = hann(segmentLength, "periodic");
frfOverlap = round(segmentLength/2);
inputForFrf = detrend(input(:), "constant");

[txyPos, f] = tfestimate(inputForFrf, detrend(pos(:), "constant"), ...
    frfWindow, frfOverlap, frfFrequencyHz, Fs);
Pd = frd(txyPos, f, "FrequencyUnit", "Hz");
Pd.Ts = Ts;

[txyVel, ~] = tfestimate(inputForFrf, detrend(vel(:), "constant"), ...
    frfWindow, frfOverlap, frfFrequencyHz, Fs);
Pd_vel = frd(txyVel, f, "FrequencyUnit", "Hz"); % input -> velocity
Pd_vel.Ts = Ts; 

[txyTor, ~] = tfestimate(inputForFrf, detrend(tor(:), "constant"), ...
    frfWindow, frfOverlap, frfFrequencyHz, Fs);
Pd_tor = frd(txyTor, f, "FrequencyUnit", "Hz"); % TargetTorque -> ActualTorque
Pd_tor.Ts = Ts; 
%%
%[text] check coherence (good if close to 1)
[coherencePos, coherenceFrequencyHz] = mscohere(inputForFrf, ...
    detrend(pos(:), "constant"), frfWindow, frfOverlap, frfFrequencyHz, Fs);
[coherenceTor, ~] = mscohere(inputForFrf, detrend(tor(:), "constant"), ...
    frfWindow, frfOverlap, frfFrequencyHz, Fs);
figure; %[output:6025b4d1]
semilogx(coherenceFrequencyHz, coherencePos, coherenceFrequencyHz, coherenceTor); %[output:6025b4d1]
ylim([0, 1]); grid on; %[output:6025b4d1]
xlabel("Frequency (Hz)"); ylabel("Coherence"); %[output:6025b4d1]
title("FRF coherence"); %[output:6025b4d1]
legend("TargetTorque to position", "TargetTorque to ActualTorque"); %[output:6025b4d1]
%%
%[text] ### Automatic data fitting of system $P${"editStyle":"visual"}
%[text] True system: $P=\\frac{1}{{\\textrm{Js}}^2 +\\textrm{Ds}}${"editStyle":"visual"}
%[text] Nominal system: $P\_n =\\frac{1}{{J\_n s}^2 +D\_n s}${"editStyle":"visual"}
%[text] optimize $J\_n${"editStyle":"visual"} and $D\_n${"editStyle":"visual"} so $P\_n${"editStyle":"visual"} becomes close to $P${"editStyle":"visual"}.
s = tf("s");
z = tf("z",Ts);

Dn = 10^(13/20);
Jn = Dn/(10*2*pi);

Ndelay = round(2e-3/Ts); % preserve a 2 ms physical delay at either sample rate
nominalFitBandHz = [1, min(300, frfMaxHz)];
fitIndex = f >= nominalFitBandHz(1) & f <= nominalFitBandHz(2) ...
    & isfinite(txyPos) & abs(txyPos) > 0 & coherencePos >= 0.8;
assert(nnz(fitIndex) >= 10, ...
    "Too few coherent FRF points are available for nominal-plant fitting.");

fitFrequencyHz = f(fitIndex);
fitResponse = txyPos(fitIndex);
sTustin = 1i*(2/Ts)*tan(pi*fitFrequencyHz*Ts);
delayResponse = exp(-1i*2*pi*fitFrequencyHz*Ts*Ndelay);
nominalResponse = @(logCoefficients) delayResponse./( ...
    exp(logCoefficients(1))*sTustin.^2 + exp(logCoefficients(2))*sTustin);
fitCostFunction = @(logCoefficients) mean(abs(log( ...
    nominalResponse(logCoefficients)./fitResponse)).^2);
[logCoefficients, nominalFitCost] = fminsearch(fitCostFunction, ...
    log([Jn, Dn]), optimset("Display", "off"));
Jn = exp(logCoefficients(1));
Dn = exp(logCoefficients(2));
fprintf("Nominal fit: Jn=%.6g, Dn=%.6g, delay=%d samples, cost=%.4g\n", ... %[output:group:8bb5dd1e] %[output:15f98edc]
    Jn, Dn, Ndelay, nominalFitCost); %[output:group:8bb5dd1e] %[output:15f98edc]

% Pdn = c2d(1/(Jn*s+Dn)/s*(1/(tau*s+1)),Ts,"tustin")/z^Ndelay; % discretized nominal plant of input -> pos
Pdn = c2d(1/(Jn*s+Dn)/s,Ts,"tustin")/z^Ndelay;

% alpha = 3;
% Pdn_test = c2d(1/(Jn*s+Dn)/s/alpha*(1/(tau*s+1)),Ts,"tustin")/z^Ndelay;

bop_ = bop;
bop_.YLim = {[-160,-20];[-180,180]};
bop_.XLim = {[1,1e3]};
figure; %[output:18ada7ef]
bode(Pd,Pdn,bop_); %[output:18ada7ef]
% bode(Pd_velocity*c2d(1/s, Ts, "tustin"),Pdn,bop_);
legend(["$P_{d}$","$P_{n}$"],"Interpreter","latex"); %[output:18ada7ef]

bop_ = bop;
bop_.YLim = {[-20,5];[-180,180]};
bop_.XLim = {[1,frfMaxHz]};
figure; %[output:02696bab]
bode(Pd_tor,bop_); %[output:02696bab]
% legend(["$P_{d}$","$P_{n}$"],"Interpreter","latex");
%%
%[text] save fitting data
%[text] load-side position will be the main objective of control for demo2 to demo4
% The selected output file is defined in config/sample_rate.m.
plantResult = struct("Pd", Pd, "Pd_tor", Pd_tor, "Pdn", Pdn, ...
    "Jn", Jn, "Dn", Dn, "Ndelay", Ndelay, "Ts", Ts, "Fs", Fs, ...
    "nominalFitBandHz", nominalFitBandHz, "nominalFitCost", nominalFitCost, ...
    "measurement_metadata", measurement_metadata, ...
    "measurement_source_path", measurement_source_path);
save_experiment_plant(runDir, plantResult);
save_experiment_figures(runDir, findall(groot, "Type", "figure"));


